node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const { v4: uuidv4 } = require('/tmp/node_modules/better-sqlite3/../uuid' || 'crypto');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

const messageId = crypto.randomUUID();
const self = db.prepare(\"SELECT * FROM ts_contacts WHERE is_self = 1\").get();
const recipient = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = '+1-347-555-0169'\").get();

const content = 'Hi Daniel, I\\'d like to set up a regular apartment cleaning schedule. The cleaning would be every Monday at 10 AM. The main focus areas are the kitchen and bathroom. You can access the apartment through the front desk. Please let me know if this works for you. Thanks!';

db.prepare(
  'INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)'
).run(
  messageId,
  self.person_id,
  self.phone_number,
  recipient.person_id,
  recipient.phone_number,
  content,
  Date.now() / 1000
);

console.log('Message sent successfully!');
console.log('Message ID:', messageId);
console.log('From:', self.name, '(' + self.phone_number + ')');
console.log('To:', recipient.name, '(' + recipient.phone_number + ')');
console.log('Content:', content);
db.close();
"

